[{"order":1,"type":"heading","text":"Angular Architecture and Core Concepts"},{"order":2,"type":"paragraph","text":"Angular is a platform and framework for building single-page client applications using HTML, CSS, and TypeScript. It's built on a component-based architecture, making it easy to create reusable UI elements. This tutorial will cover the core concepts of Angular architecture."},{"order":3,"type":"subheading","text":"Components"},{"order":4,"type":"paragraph","text":"Components are the basic building blocks of an Angular application. Each component controls a portion of the user interface and consists of three parts:"},{"order":5,"type":"bullet_point","text":"Template: An HTML file that defines the structure and layout of the component's view."},{"order":6,"type":"bullet_point","text":"Class: A TypeScript class that handles the component's logic, data, and interactions."},{"order":7,"type":"bullet_point","text":"Metadata: A decorator that provides information about the component, such as its selector, template, and styles."},{"order":8,"type":"code","text":"import { Component } from '@angular/core';

@Component({
  selector: 'app-my-component',
  templateUrl: './my-component.component.html',
  styleUrls: ['./my-component.component.css']
})
export class MyComponent {
  message = 'Hello, Angular!';
}"},{"order":9,"type":"subheading","text":"Modules"},{"order":10,"type":"paragraph","text":"Modules are containers that group related components, directives, services, and other modules. Every Angular app has at least one module, the root module, conventionally named AppModule. Modules help organize the application and promote reusability."},{"order":11,"type":"code","text":"import { NgModule } from '@angular/core';
import { BrowserModule } from '@angular/platform-browser';
import { MyComponent } from './my-component.component';

@NgModule({
  declarations: [
    MyComponent
  ],
  imports: [
    BrowserModule
  ],
  providers: [],
  bootstrap: [MyComponent]
})
export class AppModule { }"},{"order":12,"type":"subheading","text":"Services"},{"order":13,"type":"paragraph","text":"Services are classes that encapsulate reusable logic, such as data fetching, logging, or any other task that doesn't directly involve the view. They are typically injected into components using dependency injection."},{"order":14,"type":"code","text":"import { Injectable } from '@angular/core';

@Injectable({
  providedIn: 'root'
})
export class DataService {
  getData(): string {
    return 'Data from service';
  }
}"},{"order":15,"type":"subheading","text":"Templates"},{"order":16,"type":"paragraph","text":"Templates are HTML files that define the structure and layout of a component's view. They use Angular's template syntax to bind data to the view and handle user interactions."},{"order":17,"type":"code","text":"<p>{{ message }}</p>
<button (click)="handleClick()">Click me</button>"},{"order":18,"type":"subheading","text":"Metadata"},{"order":19,"type":"paragraph","text":"Metadata provides Angular with information about a class, such as its selector, template, and styles. It's defined using decorators, which are functions that modify the class definition."},{"order":20,"type":"code","text":"@Component({
  selector: 'app-my-component',
  templateUrl: './my-component.component.html',
  styleUrls: ['./my-component.component.css']
})"},{"order":21,"type":"subheading","text":"Data Binding"},{"order":22,"type":"paragraph","text":"Data binding is the process of synchronizing data between the component's class and its template. Angular supports several types of data binding:"},{"order":23,"type":"bullet_point","text":"Interpolation: Displays data from the component in the template ({{ message }})."},{"order":24,"type":"bullet_point","text":"Property Binding: Sets the value of an HTML element's property ([property]="expression")."},{"order":25,"type":"bullet_point","text":"Event Binding: Listens for events from the DOM and executes component methods ((event)="expression")."},{"order":26,"type":"bullet_point","text":"Two-Way Binding: Allows data to flow in both directions between the component and the template ([()]="expression")."},{"order":27,"type":"code","text":"<p>Interpolation: {{ message }}</p>
<input type="text" [value]="message">
<button (click)="handleClick()">Click me</button>
<input type="text" [(ngModel)]="message">"},{"order":28,"type":"subheading","text":"Directives"},{"order":29,"type":"paragraph","text":"Directives are classes that add behavior to existing elements in the DOM. Angular provides three types of directives:"},{"order":30,"type":"bullet_point","text":"Components: Directives with a template."},{"order":31,"type":"bullet_point","text":"Structural Directives: Change the DOM layout by adding, removing, or replacing elements (*ngIf, *ngFor)."},{"order":32,"type":"bullet_point","text":"Attribute Directives: Change the appearance or behavior of an element (NgStyle, NgClass)."},{"order":33,"type":"code","text":"<p *ngIf="isVisible">This is visible.</p>
<div *ngFor="let item of items">{{ item }}</div>
<p [ngStyle]="{ 'color': 'red' }">Red text</p>"},{"order":34,"type":"subheading","text":"Dependency Injection"},{"order":35,"type":"paragraph","text":"Dependency injection (DI) is a design pattern that allows components to receive dependencies from an external source rather than creating them themselves. This promotes loose coupling and testability. Angular has a powerful DI system that makes it easy to inject services and other dependencies into components."},{"order":36,"type":"code","text":"import { Component } from '@angular/core';
import { DataService } from './data.service';

@Component({
  selector: 'app-my-component',
  template: '<p>{{ data }}</p>'
})
export class MyComponent {
  data: string;

  constructor(private dataService: DataService) {
    this.data = dataService.getData();
  }
}"}]
